import java.util.*; public class Q13_HotelReservationSystem{static class Guest{String n,id;int age;Guest(String n,int a,String i){this.n=n;age=a;id=i;}public String toString(){return n+","+age+","+id;}}static class Reservation{String id,type;List<Guest>g=new ArrayList<>();Reservation(String i,String t){id=i;type=t;}public String toString(){StringBuilder s=new StringBuilder("Reservation ID: "+id+" Room: "+type+"\nGuests:\n");for(Guest x:g)s.append(x).append('\n');return s.toString();}}public static void main(String[]x){Scanner s=new Scanner(System.in);String[]p=s.nextLine().split(",");Reservation r=new Reservation(p[0],p[1]);int n=Integer.parseInt(p[2]);while(n-->0){p=s.nextLine().split(",");r.g.add(new Guest(p[0],Integer.parseInt(p[1]),p[2]));}System.out.print(r);}}
